import { get, subscribe, deriveCanSign } from '../app/store.js';
import { registerComponentPoll } from '../app/component-poll.js';
import { TX_CONFIRMED_EVENT } from '../app/contracts.js';
import { boonTypePresentation } from '../app/boons.js';
import { compactUiError } from '../app/ui-error.js';
import {
  SACRIFICE_DEITIES, FLIP_UNIT, MIN_SACRIFICE, MAX_SACRIFICE, SACRIFICE_SLOTS_PER_POOL,
  parseSacrificeAmount, readSacrifices, sacrificeFlip,
  readSacrificeHistory, sacrificeStanding, sacrificeAnySlotChance, sacrificeQuote,
} from '../app/sacrifices.js';

let readState = readSacrifices;
let donate = sacrificeFlip;
let readHistory = readSacrificeHistory;

export function formatSacrificeFlip(wei) {
  if (wei == null) return '—';
  const value = BigInt(wei);
  const whole = (value / FLIP_UNIT).toLocaleString('en-US');
  const fraction = String(value % FLIP_UNIT).padStart(18, '0').slice(0, 2).replace(/0+$/, '');
  return `${whole}${fraction ? `.${fraction}` : ''}`;
}

/** Short, explicit benefits for the six inline boon previews. */
export function compactSacrificeBoon(type, presentation = boonTypePresentation(type)) {
  if (!presentation) return { name: 'Tomorrow', effect: '—' };
  if (Number(type) === 4) return { name: 'Quest', effect: 'Shield' };
  if (Number(type) === 28) return { name: 'Whale', effect: 'Pass' };
  const amount = presentation.effect.match(/[+−-]?\d+(?:\.\d+)?%?/)?.[0] || '—';
  const sign = presentation.direction === 'down' ? '−' : '+';
  const effect = `${sign}${amount.replace(/^[+−-]/, '')}`;
  const asset = presentation.product?.startsWith('degenerette-')
    ? presentation.product.slice('degenerette-'.length).toUpperCase() : '';
  return { name: presentation.name, effect: asset ? `${effect} ${asset}` : effect };
}

function _percent(chance) {
  if (chance == null || !Number.isFinite(chance)) return null;
  const pct = chance * 100;
  if (pct >= 99.95) return '>99.9%';
  if (pct >= 10) return `${pct.toFixed(0)}%`;
  if (pct >= 1) return `${pct.toFixed(1)}%`;
  if (pct >= 0.01) return `${pct.toFixed(2)}%`;
  return '<0.01%';
}

/**
 * The one line under each altar: what the wallet already holds in TODAY's pool, and
 * what the amount in the box would make of it.
 *
 * Standing is the SUM of the wallet's existing entries, each carrying its own frozen
 * score snapshot — never a re-quote of the whole position at today's score. The
 * chance is for winning AT LEAST ONE of the three slots, because the pool draws all
 * three independently WITH REPLACEMENT.
 */
export function sacrificeOddsLine({ pool, standing, quote, historyAvailable = true } = {}) {
  if (!pool) return '';
  const entries = Number(pool.entryCount ?? 0);
  const field = `${entries.toLocaleString('en-US')} ${entries === 1 ? 'entry' : 'entries'} · `
    + `${formatSacrificeFlip(pool.totalDonatedWei ?? 0n)} FLIP in the pool`;
  if (pool.awardedMask) return `${field} · drawn`;

  const held = standing && standing.count > 0 ? standing : null;
  const parts = [field];
  if (held) {
    const chance = _percent(sacrificeAnySlotChance(held.weight, pool.totalWeight));
    parts.push(`you: ${held.count} ${held.count === 1 ? 'entry' : 'entries'}`
      + `, ${formatSacrificeFlip(held.amountWei)} FLIP`
      + (chance ? ` · ${chance} for at least one of ${SACRIFICE_SLOTS_PER_POOL}` : ''));
  } else if (!historyAvailable) {
    parts.push('your standing is unavailable');
  }
  if (quote) {
    // `pool.totalWeight` ALREADY contains this wallet's existing entries, so the
    // post-sacrifice numerator is held + proposed and the denominator is the pool
    // plus the proposed weight — never the pool plus held plus proposed.
    const after = sacrificeAnySlotChance(
      BigInt(held?.weight ?? 0n) + BigInt(quote.weight),
      BigInt(pool.totalWeight ?? 0n) + BigInt(quote.weight),
    );
    const pct = _percent(after);
    parts.push(`this sacrifice: ${quote.units} × ${quote.multiplier.toFixed(2)}×`
      + (pct ? ` → ${pct}` : ''));
    if (quote.remainderWei > 0n) {
      parts.push(`${formatSacrificeFlip(quote.remainderWei)} FLIP over a whole 100 earns no extra weight`);
    }
  }
  return parts.join(' · ');
}

/** Past awards, newest first, as short readable lines. */
export function sacrificeAwardLines(awards, { limit = 5 } = {}) {
  const byKey = new Map(SACRIFICE_DEITIES.map((deity) => [String(deity.address || '').toLowerCase(), deity.name]));
  return (Array.isArray(awards) ? awards : [])
    .slice()
    .sort((a, b) => Number(b?.day ?? 0) - Number(a?.day ?? 0))
    .slice(0, Math.max(0, limit))
    .map((row) => {
      const name = byKey.get(String(row?.issuer || '').toLowerCase()) || 'a deity';
      // The route serves the same value under both spellings; take either.
      const boon = compactSacrificeBoon(Number(row?.boonType ?? row?.boonKind ?? 0));
      // `day` is the PARTICIPATION day on both events; the award lands on day + 1.
      const day = Number(row?.day);
      const when = Number.isFinite(day) ? `day ${day + 1}` : 'a past day';
      return `${when} · ${name} · ${boon.name} ${boon.effect}`;
    });
}

export function sacrificeLockReason({ state, deityKey, amount, connected, mode, canSign, busy } = {}) {
  if (busy) return 'Sacrifice in progress…';
  if (!state) return 'Sacrifice data is unavailable. Try refreshing.';
  if (state.ended) return 'Sacrifices are closed. The game has ended.';
  if (!state.menuReady) return 'Tomorrow’s boons appear after today’s draw.';
  if (!connected) return 'Connect your wallet to sacrifice FLIP.';
  if (mode !== 'self') return 'Open your own wallet view to sacrifice FLIP.';
  if (!canSign) return 'Your wallet connection is not ready.';
  const pool = state.pools.find((item) => item.key === deityKey);
  if (!pool || pool.awardedMask) return 'This deity’s draw is closed.';
  if (state.balanceWei == null || state.multiplierUnits == null) return 'Your FLIP balance and draw weight are unavailable.';
  if (amount == null || amount < MIN_SACRIFICE || amount > MAX_SACRIFICE) return 'Enter 100–25,000 FLIP per sacrifice.';
  if (amount > state.balanceWei) return 'Not enough FLIP in your wallet.';
  return '';
}

class AppSacrificePanel extends HTMLElement {
  #mounted = false;
  #state = null;
  #busy = null;
  #loading = true;
  #seq = 0;
  #queued = false;
  #unsubs = [];
  #stopPoll = null;
  #confirmed = null;
  #readAt = 0;
  // Indexer decoration. `available:false` means the history ROUTE is not answering —
  // never that this wallet has no history — so the copy has to stay honest about it.
  #history = { available: false, entries: [], awards: [] };

  connectedCallback() {
    if (this.#mounted) return;
    this.#mounted = true;
    this.#shell();
    this.#wire();
    for (const key of ['connected.address', 'viewing.address', 'ui.mode', 'ui.chainOk']) {
      this.#unsubs.push(subscribe(key, () => {
        this.#seq += 1;
        this.#state = null;
        for (const deity of SACRIFICE_DEITIES) this.#feedback(deity.key, '');
        this.#queueRefresh();
      }));
    }
    this.#confirmed = () => this.#queueRefresh();
    document.addEventListener(TX_CONFIRMED_EVENT, this.#confirmed);
    this.#stopPoll = registerComponentPoll(() => this.#refresh(), 30_000);
    this.#refresh();
  }

  disconnectedCallback() {
    this.#mounted = false;
    this.#seq += 1;
    this.#stopPoll?.();
    this.#unsubs.splice(0).forEach((unsubscribe) => unsubscribe());
    document.removeEventListener(TX_CONFIRMED_EVENT, this.#confirmed);
  }

  #node(name) { return this.querySelector(`[data-sacrifice="${name}"]`); }

  #shell() {
    this.innerHTML = `
      <section class="sacrifice" aria-label="Sacrifice FLIP for tomorrow’s deity boons">
        ${SACRIFICE_DEITIES.map((deity) => `
          <div class="sacrifice__side" data-deity="${deity.key}" aria-label="Sacrifice to the God of ${deity.name}">
            <span class="sacrifice__deity">
            <span class="sacrifice__boons" aria-label="Tomorrow’s three boons">
              ${[0, 1, 2].map((slot) => `
                <span class="sacrifice__boon" data-slot="${slot}">
                  <i class="sacrifice__boon-mark" aria-hidden="true" hidden><img class="sacrifice__boon-icon" alt="" hidden></i>
                  <small data-prize-name>Tomorrow</small><strong data-prize-effect>—</strong>
                </span>`).join('')}
            </span>
            </span>
            <button class="sacrifice__submit" type="button" data-sacrifice="submit-${deity.key}"
                    data-write data-write-locked disabled>
              <span class="sacrifice__submit-copy"><b data-sacrifice="submit-label-${deity.key}">SACRIFICE</b><small>TO RECEIVE</small><small>A BLESSING?</small></span>
              <span class="sacrifice__submit-seal"><img class="sacrifice__submit-badge" src="${deity.symbol}" alt="${deity.name}" width="50" height="50"></span>
            </button>
            <p class="sacrifice__odds" data-sacrifice="odds-${deity.key}" hidden></p>
            <p class="sacrifice__feedback" data-sacrifice="feedback-${deity.key}" role="status" hidden></p>
          </div>`).join(`
            <label class="sacrifice__amount">
              <input data-sacrifice="amount" type="text" inputmode="decimal" value="1000"
                     autocomplete="off" spellcheck="false" aria-label="FLIP to sacrifice to either deity"
                     title="100–25,000 FLIP per sacrifice">
              <span>FLIP</span>
            </label>`)}
        <div class="sacrifice__history" data-sacrifice="history" hidden>
          <h4 class="sacrifice__history-title">Blessings received</h4>
          <ul class="sacrifice__history-list" data-sacrifice="history-list"></ul>
        </div>
      </section>`;
  }

  #wire() {
    this.#node('amount').addEventListener('input', () => {
      for (const deity of SACRIFICE_DEITIES) this.#feedback(deity.key, '');
      this.#render();
    });
    for (const deity of SACRIFICE_DEITIES) {
      this.#node(`submit-${deity.key}`).addEventListener('click', () => this.#submit(deity.key));
    }
  }

  #queueRefresh() {
    if (this.#queued || !this.#mounted) return;
    this.#queued = true;
    this.#loading = true;
    this.#render();
    queueMicrotask(() => { this.#queued = false; if (this.#mounted) this.#refresh(); });
  }

  async #refresh() {
    const seq = ++this.#seq;
    this.#loading = true;
    this.#render();
    const player = get('ui.mode') === 'self' ? get('connected.address') : null;
    // The indexer history is DECORATION and rides beside the chain read rather than
    // in front of it: a 404 or a wedged route must never hold the altar closed.
    const historyRead = player
      ? readHistory(player).catch(() => ({ available: false, entries: [], awards: [] }))
      : Promise.resolve({ available: false, entries: [], awards: [] });
    let state = null;
    try { state = await readState({ player }); } catch { /* unavailable deployment or RPC */ }
    if (!this.#mounted || seq !== this.#seq) return;
    this.#state = state;
    this.#readAt = Date.now();
    this.#loading = false;
    this.#render();
    const history = await historyRead;
    if (!this.#mounted || seq !== this.#seq) return;
    this.#history = history;
    this.#render();
  }

  #reason(deityKey) {
    if (this.#loading) return 'Reading tomorrow’s boons…';
    if (this.#state && Date.now() - this.#readAt > 60_000) return 'Refresh the pool before sacrificing.';
    return sacrificeLockReason({ state: this.#state, deityKey,
      amount: parseSacrificeAmount(this.#node('amount').value),
      connected: get('connected.address'), mode: get('ui.mode'), canSign: deriveCanSign(), busy: this.#busy });
  }

  #render() {
    const state = this.#state;
    const input = this.#node('amount');
    const amount = parseSacrificeAmount(input.value);
    input.disabled = Boolean(this.#busy);
    input.title = `100–25,000 FLIP · wallet ${formatSacrificeFlip(state?.balanceWei)} FLIP`;
    for (const deity of SACRIFICE_DEITIES) {
      const side = this.querySelector(`[data-deity="${deity.key}"]`);
      const pool = state?.pools.find((item) => item.key === deity.key);
      const tomorrow = state ? `Tomorrow’s boons · day ${state.awardDay}` : 'Tomorrow’s boons';
      side.querySelector('.sacrifice__boons').setAttribute('aria-label', tomorrow);
      side.querySelectorAll('[data-slot]').forEach((slot) => {
        const type = pool?.slots[Number(slot.dataset.slot)];
        const presentation = state?.menuReady && type ? boonTypePresentation(type) : null;
        const boon = compactSacrificeBoon(type, presentation);
        slot.querySelector('[data-prize-name]').textContent = presentation ? boon.name : 'Tomorrow';
        slot.querySelector('[data-prize-effect]').textContent = presentation ? boon.effect : '—';
        slot.title = presentation ? `${tomorrow}: ${presentation.detail}` : (this.#loading ? 'Loading boons…' : 'Boons unavailable');
        const mark = slot.querySelector('.sacrifice__boon-mark');
        const icon = slot.querySelector('.sacrifice__boon-icon');
        mark.hidden = !presentation;
        icon.hidden = !presentation?.icon;
        if (presentation?.icon) icon.src = presentation.icon;
        else icon.removeAttribute('src');
        slot.style.setProperty('--boon-amount', presentation?.amountColor || '#93c5fd');
        slot.dataset.boonProduct = presentation?.product || '';
        slot.dataset.boonDirection = presentation?.direction || '';
        slot.dataset.boonStrength = presentation?.strength || '';
      });
      const odds = this.#node(`odds-${deity.key}`);
      if (odds) {
        const standing = sacrificeStanding(this.#history.entries, {
          issuer: deity.address,
          day: state?.day,
        });
        const quote = state && amount != null && state.multiplierUnits != null && pool
          ? sacrificeQuote(amount, state.multiplierUnits, pool.totalWeight)
          : null;
        const line = sacrificeOddsLine({
          pool,
          standing,
          quote,
          historyAvailable: this.#history.available,
        });
        odds.textContent = line;
        odds.hidden = !line;
      }
      const reason = this.#reason(deity.key);
      const submit = this.#node(`submit-${deity.key}`);
      this.#node(`submit-label-${deity.key}`).textContent = this.#busy === deity.key ? 'PENDING…' : 'SACRIFICE';
      submit.disabled = Boolean(reason);
      submit.toggleAttribute('data-write-locked', Boolean(reason));
      submit.setAttribute('data-write-lock-title', reason);
      submit.setAttribute('aria-label', `Sacrifice FLIP to the God of ${deity.name} for tomorrow’s three boon draws`);
      submit.title = reason || `Sacrifice ${formatSacrificeFlip(amount)} FLIP to ${deity.name} for tomorrow’s three boon draws`;
    }
    this.#renderHistory();
  }

  #renderHistory() {
    const wrap = this.#node('history');
    const list = this.#node('history-list');
    if (!wrap || !list) return;
    const lines = sacrificeAwardLines(this.#history.awards);
    wrap.hidden = lines.length === 0;
    list.replaceChildren(...lines.map((line) => {
      const item = document.createElement('li');
      item.className = 'sacrifice__history-item';
      item.textContent = line;
      return item;
    }));
  }

  #feedback(deityKey, message, error = false) {
    const node = this.#node(`feedback-${deityKey}`);
    node.textContent = message;
    node.hidden = !message;
    node.classList.toggle('sacrifice__feedback--error', error);
  }

  async #submit(deityKey) {
    if (this.#reason(deityKey)) { this.#render(); return; }
    const donor = get('connected.address');
    const amount = parseSacrificeAmount(this.#node('amount').value);
    const expectedDay = this.#state.day;
    const stillHere = () => this.#mounted && donor === get('connected.address') && get('ui.mode') === 'self';
    this.#busy = deityKey;
    this.#feedback(deityKey, 'Confirm in your wallet.');
    this.#render();
    try {
      const result = await donate({ deityKey, amount, expectedDay, onSubmitted: () => {
        if (stillHere()) this.#feedback(deityKey, 'Waiting for confirmation…');
      } });
      if (stillHere()) this.#feedback(deityKey, result.awardDay == null
        ? 'Sacrifice confirmed.'
        : `Entered all three draws for day ${result.awardDay}.`);
      if (this.#mounted) this.#queueRefresh();
    } catch (error) {
      if (stillHere()) this.#feedback(deityKey, compactUiError(error, 'Sacrifice did not go through. Try again.'), true);
      if (this.#mounted) this.#queueRefresh();
    } finally {
      this.#busy = null;
      if (this.#mounted) this.#render();
    }
  }

}

if (!customElements.get('app-sacrifice-panel')) customElements.define('app-sacrifice-panel', AppSacrificePanel);

/** Dependency seam for browser fixtures and isolated component tests. */
export function __setSacrificePanelDepsForTest({
  read = readSacrifices,
  sacrifice = sacrificeFlip,
  history = readSacrificeHistory,
} = {}) {
  readState = read;
  donate = sacrifice;
  readHistory = history;
}
